<script setup>
const props=defineProps({fields:{type:Array,default:()=>[]},modelValue:{type:Object,required:true},disabled:Boolean});const emit=defineEmits(['update:modelValue']);function set(key,value){emit('update:modelValue',{...props.modelValue,[key]:value})}
</script>
<template><div class="grid gap-4 sm:grid-cols-2"><div v-for="field in fields" :key="field.key" class="admin-field" :class="field.type==='textarea'?'sm:col-span-2':''"><label v-if="field.type!=='checkbox'" :for="`dynamic-${field.key}`">{{field.label}} <span v-if="field.required">*</span></label><p v-if="field.description" class="mb-2 text-xs text-neutral-500">{{field.description}}</p><textarea v-if="field.type==='textarea'" :id="`dynamic-${field.key}`" :value="modelValue[field.key]??field.default_value??''" :disabled="disabled" rows="3" @input="set(field.key,$event.target.value)"/><input v-else-if="['text','number','date'].includes(field.type)" :id="`dynamic-${field.key}`" :type="field.type" :value="modelValue[field.key]??field.default_value??''" :disabled="disabled" @input="set(field.key,field.type==='number'?Number($event.target.value):$event.target.value)"><label v-else-if="field.type==='checkbox'" class="flex items-center gap-3 border p-3"><input type="checkbox" :checked="modelValue[field.key]??field.default_value??false" :disabled="disabled" @change="set(field.key,$event.target.checked)"> {{field.label}}</label><select v-else :id="`dynamic-${field.key}`" :value="modelValue[field.key]??field.default_value??''" :multiple="field.type==='multi_select'" :disabled="disabled" @change="set(field.key,field.type==='multi_select'?[...$event.target.selectedOptions].map(o=>o.value):$event.target.value)"><option value="">Select…</option><option v-for="option in field.options||[]" :key="option.value" :value="option.value">{{option.label}}</option></select></div></div></template>